'use strict';

const http = require('http');
const { URL } = require('url');

function createApp() {
  const routes = [];

  function app(req, res) {
    // Provide the small subset of Express' response API that this project uses.
    if (typeof res.status !== 'function') {
      res.status = function status(code) {
        res.statusCode = code;
        return res;
      };
    }

    if (typeof res.json !== 'function') {
      res.json = function json(payload) {
        if (!res.headersSent) {
          res.setHeader('Content-Type', 'application/json; charset=utf-8');
        }
        res.end(JSON.stringify(payload));
      };
    }

    const method = req.method || 'GET';
    const pathname = new URL(req.url || '/', 'http://localhost').pathname;
    const route = routes.find((candidate) => candidate.method === method && candidate.path === pathname);

    if (!route) {
      res.statusCode = 404;
      res.setHeader('Content-Type', 'application/json; charset=utf-8');
      res.end(JSON.stringify({ error: 'Not Found' }));
      return;
    }

    route.handler(req, res);
  }

  app.get = function get(path, handler) {
    routes.push({ method: 'GET', path, handler });
    return app;
  };

  app.listen = function listen(...args) {
    const server = http.createServer(app);
    return server.listen(...args);
  };

  return app;
}

module.exports = createApp;

