// Simple dependency-free HTTP application.
// Exports a request handler compatible with Node's http.createServer()
// and tools such as supertest, while also providing a small Express-like
// `get` and `listen` API for this app's routes.

const http = require('http');
const { URL } = require('url');

const routes = new Map();

function createResponse(res) {
  if (typeof res.json !== 'function') {
    res.json = (body) => {
      const payload = JSON.stringify(body);
      res.statusCode = res.statusCode || 200;
      res.setHeader('Content-Type', 'application/json; charset=utf-8');
      res.setHeader('Content-Length', Buffer.byteLength(payload));
      res.end(payload);
    };
  }

  if (typeof res.status !== 'function') {
    res.status = (code) => {
      res.statusCode = code;
      return res;
    };
  }

  return res;
}

function app(req, res) {
  createResponse(res);

  const method = (req.method || 'GET').toUpperCase();
  const pathname = new URL(req.url || '/', 'http://localhost').pathname;
  const handler = routes.get(`${method} ${pathname}`);

  if (!handler) {
    return res.status(404).json({ error: 'Not Found' });
  }

  return handler(req, res);
}

app.get = (path, handler) => {
  routes.set(`GET ${path}`, handler);
  return app;
};

app.listen = (...args) => http.createServer(app).listen(...args);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;

