const assert = require('assert');
const http = require('http');
const app = require('./app');

function request(server, path) {
  const { port } = server.address();

  return new Promise((resolve, reject) => {
    const req = http.get({ hostname: '127.0.0.1', port, path }, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        try {
          resolve({
            statusCode: res.statusCode,
            headers: res.headers,
            body: body ? JSON.parse(body) : undefined,
          });
        } catch (error) {
          reject(error);
        }
      });
    });

    req.on('error', reject);
  });
}

async function run() {
  const server = app.listen(0);

  try {
    const health = await request(server, '/health');
    assert.strictEqual(health.statusCode, 200);
    assert.strictEqual(health.body.status, 'ok');
    assert.match(health.body.timestamp, /^\d{4}-\d{2}-\d{2}T/);

    const users = await request(server, '/users');
    assert.strictEqual(users.statusCode, 200);
    assert.deepStrictEqual(users.body, [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);

    const missing = await request(server, '/missing');
    assert.strictEqual(missing.statusCode, 404);
    assert.deepStrictEqual(missing.body, { error: 'Not Found' });
  } finally {
    await new Promise((resolve, reject) => {
      server.close((error) => (error ? reject(error) : resolve()));
    });
  }
}

run()
  .then(() => {
    console.log('All tests passed');
  })
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });

