// Simple application for agent to work on
// Uses only Node's built-in modules so the project can run without network installs.

const http = require('node:http');

const routes = new Map();

function sendJson(res, statusCode, body) {
  const payload = JSON.stringify(body);
  res.writeHead(statusCode, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function app(req, res) {
  const url = new URL(req.url, 'http://localhost');
  const handler = routes.get(`${req.method} ${url.pathname}`);

  if (!handler) {
    return sendJson(res, 404, { error: 'Not found' });
  }

  const response = {
    status(code) {
      res.statusCode = code;
      return response;
    },
    json(body) {
      sendJson(res, res.statusCode || 200, body);
    },
  };

  handler(req, response);
}

app.get = (path, handler) => {
  routes.set(`GET ${path}`, handler);
  return app;
};

app.listen = (...args) => http.createServer(app).listen(...args);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

if (require.main === module) {
  const port = process.env.PORT || 3000;
  app.listen(port, () => {
    console.log(`Server running on port ${port}`);
  });
}

module.exports = app;

