const assert = require('node:assert/strict');
const app = require('./app');

async function getJson(baseUrl, path) {
  const response = await fetch(`${baseUrl}${path}`);
  return {
    status: response.status,
    body: await response.json(),
    contentType: response.headers.get('content-type'),
  };
}

async function run() {
  const server = app.listen(0);

  try {
    await new Promise((resolve, reject) => {
      server.once('listening', resolve);
      server.once('error', reject);
    });

    const baseUrl = `http://127.0.0.1:${server.address().port}`;

    const health = await getJson(baseUrl, '/health');
    assert.equal(health.status, 200);
    assert.match(health.contentType, /application\/json/);
    assert.equal(health.body.status, 'ok');
    assert.ok(!Number.isNaN(Date.parse(health.body.timestamp)));

    const users = await getJson(baseUrl, '/users');
    assert.equal(users.status, 200);
    assert.deepEqual(users.body, [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);

    const missing = await getJson(baseUrl, '/missing');
    assert.equal(missing.status, 404);
    assert.deepEqual(missing.body, { error: 'Not found' });
  } finally {
    await new Promise((resolve, reject) => {
      server.close((error) => (error ? reject(error) : resolve()));
    });
  }
}

run()
  .then(() => console.log('All tests passed.'))
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });

