// Simple application for agent to work on
// This app intentionally uses only Node's built-in HTTP module so the project
// can build and test without downloading external dependencies.

const http = require('http');

const routes = new Map();

function sendJson(res, statusCode, payload) {
  const body = JSON.stringify(payload);
  res.writeHead(statusCode, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
  });
  res.end(body);
}

function app(req, res) {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  const handler = routes.get(`${req.method} ${url.pathname}`);

  res.json = (payload) => sendJson(res, res.statusCode || 200, payload);

  if (!handler) {
    return sendJson(res, 404, { error: 'Not Found' });
  }

  return handler(req, res);
}

app.get = (path, handler) => {
  routes.set(`GET ${path}`, handler);
};

app.listen = (...args) => http.createServer(app).listen(...args);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

if (require.main === module) {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}

module.exports = app;

