  return new Promise((resolve, reject) => {
    const server = app.listen(0, () => resolve(server));
    server.on('error', reject);
  });
}

async function getJson(server, path) {
  const { port } = server.address();
  const response = await fetch(`http://127.0.0.1:${port}${path}`);
  const body = await response.json();
  return { response, body };
}

test('GET /health returns ok status and a timestamp', async () => {
  const server = await startServer();
  try {
    const { response, body } = await getJson(server, '/health');

    assert.equal(response.status, 200);
    assert.equal(body.status, 'ok');
    assert.ok(!Number.isNaN(Date.parse(body.timestamp)));
  } finally {
    await new Promise((resolve) => server.close(resolve));
  }
});

test('GET /users returns the expected users', async () => {
  const server = await startServer();
  try {
    const { response, body } = await getJson(server, '/users');

    assert.equal(response.status, 200);
    assert.deepEqual(body, [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } finally {
    await new Promise((resolve) => server.close(resolve));
  }
});

